    sprint_30: { name: "30ਮੀ ਸਪ੍ਰਿੰਟ", cues: "ਪੂਰੀ ਰਿਕਵਰੀ ਨਾਲ ਛੋਟੇ ਵੱਧ ਤੋਂ ਵੱਧ ਸਪ੍ਰਿੰਟ। ਅਲੈਕਟਿਕ ਸ਼ਕਤੀ ਅਤੇ ਧਮਾਕੇਦਾਰਤਾ।" },
    sprint_60: { name: "60ਮੀ ਸਪ੍ਰਿੰਟ", cues: "ਪੂਰੀ ਰਿਕਵਰੀ ਨਾਲ ਵੱਧ ਤੋਂ ਵੱਧ ਸਪ੍ਰਿੰਟ। ਗਤੀ ਅਤੇ ਸ਼ਕਤੀ।" },
