    recovery_jog: { name: "ਰਿਕਵਰੀ ਜੌਗ", cues: "ਬਹੁਤ ਹੌਲੀ, ਛੋਟੀ ਦੌੜ। ਬਿਨਾਂ ਵਾਧੂ ਭਾਰ ਦੇ ਸਰਗਰਮ ਰਿਕਵਰੀ ਨੂੰ ਉਤਸ਼ਾਹਿਤ ਕਰਦੀ ਹੈ।" },
    strides: { name: "ਸਟਰਾਈਡਸ", cues: "80-100ਮੀ ਲਗਭਗ ਵੱਧ ਤੋਂ ਵੱਧ ਤੱਕ ਪ੍ਰਗਤੀਸ਼ੀਲ, ਸਾਫ਼ ਤਕਨੀਕ। ਨਿਊਰੋਮਸਕੂਲਰ ਸਰਗਰਮੀ।" },

    bag_intervals: { name: "ਬੈਗ ਇੰਟਰਵਲ", cues: "ਵੱਧ ਤੋਂ ਵੱਧ ਧਮਾਕੇਦਾਰਤਾ (15ਸੈ) ਅਤੇ ਰਿਕਵਰੀ ਤਕਨੀਕ (45ਸੈ) ਵਿਚਕਾਰ ਬਦਲੋ। ਖੇਡ-ਵਿਸ਼ੇਸ਼ ਕੰਡੀਸ਼ਨਿੰਗ।" },
    circuit_metcon: { name: "ਮੈਟਾਬੋਲਿਕ ਸਰਕਟ", cues: "ਬਿਨਾਂ ਰੁਕੇ ਘੁੰਮਦੇ ਸਟੇਸ਼ਨ (ਬਰਪੀ, ਛਾਲਾਂ, ਮੁੱਕੇ, ਕੋਰ)। ਥਕਾਵਟ ਦਾ ਵਿਰੋਧ।" },
